import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"Push Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"backend/push-notifications.md","filePath":"backend/push-notifications.md"}`),a={name:`backend/push-notifications.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e(`<h1 id="push-notifications" tabindex="-1">Push Notifications <a class="header-anchor" href="#push-notifications" aria-label="Permalink to &quot;Push Notifications&quot;">​</a></h1><p>TechyNews uses Web Push Notifications to alert anonymous visitors when new articles are published.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><ul><li><strong>Package:</strong> <code>laravel-notification-channels/webpush</code> (wraps <code>minishlink/web-push</code>)</li><li><strong>Database:</strong> <code>push_subscribers</code> table (Model: <code>App\\Models\\PushSubscriber</code>) and <code>push_subscriptions</code> table (from the package).</li><li><strong>Service Worker:</strong> <code>public/sw.js</code> handles receiving the push event and displaying the notification.</li><li><strong>Frontend:</strong> <code>resources/js/Components/PushSubscribe.jsx</code> handles asking for permission and sending the subscription to the backend.</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>When a user clicks the subscribe button, the browser requests notification permission.</li><li>If granted, the frontend registers the Service Worker (<code>sw.js</code>) and requests a push subscription from the browser using the <code>VITE_VAPID_PUBLIC_KEY</code>.</li><li>The frontend sends the subscription details (endpoint, keys) to <code>POST /push/subscribe</code>.</li><li>The backend uses the <code>PushSubscriptionController</code> to save the subscription. Since our users are mostly anonymous, we link it to a <code>PushSubscriber</code> model which uses a <code>guest_id</code> (IP or cookie-based).</li><li>When a new article is generated via <code>news:generate-daily</code>, the <code>App\\Notifications\\NewArticlePublished</code> notification is dispatched to all <code>PushSubscriber</code> models.</li><li>The service worker receives the push event and displays it. Clicking the notification opens the article.</li></ol><h2 id="vapid-keys" tabindex="-1">VAPID Keys <a class="header-anchor" href="#vapid-keys" aria-label="Permalink to &quot;VAPID Keys&quot;">​</a></h2><p>Web push requires VAPID keys. These are set in the <code>.env</code> file:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VAPID_PUBLIC_KEY=your_public_key</span></span>
<span class="line"><span>VAPID_PRIVATE_KEY=your_private_key</span></span>
<span class="line"><span>VITE_VAPID_PUBLIC_KEY=&quot;\${VAPID_PUBLIC_KEY}&quot;</span></span></code></pre></div><p>To generate new keys, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webpush:vapid</span></span></code></pre></div>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};